# =============================================================================
# ModelNew — SOL problem 002: Conv3x3 -> GN -> SiLU -> Conv3x3 -> GN -> SiLU -> +residual
#
# Method: CUDA_Graph_Capture_Replay_StaticBuffers
#   * whole fused chain (2x cuDNN conv + 2x fused GN/SiLU custom kernels) captured
#     once into a CUDA graph on static channels_last buffers;
#   * the ONLY per-call work is (a) a custom shared-memory tiled NCHW->NHWC
#     transpose kernel that fills the static input buffer with fully coalesced
#     128B stores, and (b) graph replay.
#   * residual add now happens in NHWC inside gn_silu_res_apply_nchw (reads the
#     same static channels_last input buffer), and the on-chip transpose emits a
#     contiguous NCHW output — no extra memory pass.
# Precision: fp32 storage + fp32 arithmetic everywhere, fp32 reduction accumulators.
# =============================================================================

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

_CUDA_SRC = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <algorithm>

#define CPG   8          // channels per group (C=256, G=32)
#define VPP   2          // float4 vectors per pixel per group (CPG/4)
#define NTHR  256
#define PCHUNK 128       // pixels processed per shared-memory tile (NTHR/VPP)

__device__ __forceinline__ void warpReduce2(float &a, float &b) {
#pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        a += __shfl_down_sync(0xffffffffu, a, off);
        b += __shfl_down_sync(0xffffffffu, b, off);
    }
}

__device__ __forceinline__ float silu_f(float v) {
    return v / (1.0f + expf(-v));
}

// ---------------------------------------------------------------------------
// NCHW -> NHWC shared-memory tiled transpose (32x32 tile, 33-wide padding).
// grid = (HW/32, C/32, N), block = (32, 8).
// Loads: 32 contiguous floats per warp (coalesced).
// Stores: 32 contiguous channels per warp = 128B (coalesced).
// ---------------------------------------------------------------------------
__global__ void nchw2nhwc_kernel(const float* __restrict__ src,
                                 float* __restrict__ dst,
                                 int HW, int C)
{
    __shared__ float sm[32][33];

    const int hw0 = blockIdx.x * 32;
    const int c0  = blockIdx.y * 32;
    const int n   = blockIdx.z;

    const float* s = src + (long long)n * (long long)C * HW;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

#pragma unroll
    for (int i = 0; i < 32; i += 8) {
        sm[ty + i][tx] = s[(long long)(c0 + ty + i) * HW + (hw0 + tx)];
    }
    __syncthreads();

    float* d = dst + (long long)n * (long long)HW * C;
#pragma unroll
    for (int i = 0; i < 32; i += 8) {
        const int lhw = ty + i;
        d[(long long)(hw0 + lhw) * C + (c0 + tx)] = sm[tx][lhw];
    }
}

// ---------------------------------------------------------------------------
// Pass 1: partial sums / sums-of-squares over a pixel chunk of one (n,g) group.
// grid = (K, N*G), block = 256.   Input is channels-last (NHWC).
// ---------------------------------------------------------------------------
__global__ void gn_stats_kernel(const float* __restrict__ inp,
                                float* __restrict__ partial,
                                int HW, int C, int G, int chunk, int K)
{
    const int blk = blockIdx.x;
    const int ng  = blockIdx.y;
    const int n   = ng / G;
    const int g   = ng - n * G;

    const int pstart = blk * chunk;
    int pend = pstart + chunk;
    if (pend > HW) pend = HW;

    const float* base = inp + (long long)n * HW * C + (long long)g * CPG;

    const int tid     = threadIdx.x;
    const int j       = tid & (VPP - 1);
    const int p0      = tid / VPP;
    const int pstride = NTHR / VPP;

    float s = 0.f, ss = 0.f;
    for (int p = pstart + p0; p < pend; p += pstride) {
        const float4 v = *reinterpret_cast<const float4*>(base + (long long)p * C + j * 4);
        s  += v.x + v.y + v.z + v.w;
        ss += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }

    __shared__ float sa[NTHR / 32];
    __shared__ float sb[NTHR / 32];
    const int lane = tid & 31;
    const int wid  = tid >> 5;
    warpReduce2(s, ss);
    if (lane == 0) { sa[wid] = s; sb[wid] = ss; }
    __syncthreads();
    if (wid == 0) {
        const int nw = NTHR / 32;
        s  = (lane < nw) ? sa[lane] : 0.f;
        ss = (lane < nw) ? sb[lane] : 0.f;
        warpReduce2(s, ss);
        if (lane == 0) {
            partial[((long long)ng * K + blk) * 2 + 0] = s;
            partial[((long long)ng * K + blk) * 2 + 1] = ss;
        }
    }
}

// ---------------------------------------------------------------------------
// Pass 2: finalize (mean, rstd) per (n,g).  grid = N*G, block = 32.
// ---------------------------------------------------------------------------
__global__ void gn_finalize_kernel(const float* __restrict__ partial,
                                   float* __restrict__ stats,
                                   int K, float invcount, float eps)
{
    const int ng = blockIdx.x;
    float s = 0.f, ss = 0.f;
    for (int i = threadIdx.x; i < K; i += 32) {
        s  += partial[((long long)ng * K + i) * 2 + 0];
        ss += partial[((long long)ng * K + i) * 2 + 1];
    }
    warpReduce2(s, ss);
    if (threadIdx.x == 0) {
        const float mean = s * invcount;
        float var = ss * invcount - mean * mean;
        if (var < 0.f) var = 0.f;
        stats[ng * 2 + 0] = mean;
        stats[ng * 2 + 1] = rsqrtf(var + eps);
    }
}

// ---------------------------------------------------------------------------
// Pass 3a: normalize * gamma + beta -> SiLU, NHWC in / NHWC out.
// grid = (K, N*G), block = 256.
// ---------------------------------------------------------------------------
__global__ void gn_silu_apply_nhwc(const float* __restrict__ inp,
                                   float* __restrict__ out,
                                   const float* __restrict__ gamma,
                                   const float* __restrict__ beta,
                                   const float* __restrict__ stats,
                                   int HW, int C, int G, int chunk)
{
    const int blk = blockIdx.x;
    const int ng  = blockIdx.y;
    const int n   = ng / G;
    const int g   = ng - n * G;

    const float mean = stats[ng * 2 + 0];
    const float rstd = stats[ng * 2 + 1];

    const int tid     = threadIdx.x;
    const int j       = tid & (VPP - 1);
    const int p0      = tid / VPP;
    const int pstride = NTHR / VPP;

    const float4 gm = *reinterpret_cast<const float4*>(gamma + g * CPG + j * 4);
    const float4 bt = *reinterpret_cast<const float4*>(beta  + g * CPG + j * 4);

    const float* ibase = inp + (long long)n * HW * C + (long long)g * CPG;
    float*       obase = out + (long long)n * HW * C + (long long)g * CPG;

    const int pstart = blk * chunk;
    int pend = pstart + chunk;
    if (pend > HW) pend = HW;

    for (int p = pstart + p0; p < pend; p += pstride) {
        const long long off = (long long)p * C + j * 4;
        const float4 v = *reinterpret_cast<const float4*>(ibase + off);
        float4 o;
        o.x = silu_f((v.x - mean) * rstd * gm.x + bt.x);
        o.y = silu_f((v.y - mean) * rstd * gm.y + bt.y);
        o.z = silu_f((v.z - mean) * rstd * gm.z + bt.z);
        o.w = silu_f((v.w - mean) * rstd * gm.w + bt.w);
        *reinterpret_cast<float4*>(obase + off) = o;
    }
}

// ---------------------------------------------------------------------------
// Pass 3b: normalize -> SiLU -> + residual(NHWC), NHWC in / NCHW contiguous out.
// On-chip transpose through shared memory keeps both loads and stores coalesced.
// grid = (K, N*G), block = 256 (must equal NTHR).
// ---------------------------------------------------------------------------
__global__ void gn_silu_res_apply_nchw(const float* __restrict__ inp,
                                       const float* __restrict__ res,
                                       float* __restrict__ out,
                                       const float* __restrict__ gamma,
                                       const float* __restrict__ beta,
                                       const float* __restrict__ stats,
                                       int HW, int C, int G, int chunk)
{
    __shared__ float sh[CPG * (PCHUNK + 1)];

    const int blk = blockIdx.x;
    const int ng  = blockIdx.y;
    const int n   = ng / G;
    const int g   = ng - n * G;

    const float mean = stats[ng * 2 + 0];
    const float rstd = stats[ng * 2 + 1];

    const int tid = threadIdx.x;
    const int j   = tid & (VPP - 1);   // which float4 inside the group
    const int pl  = tid / VPP;         // local pixel index (0..127)

    const float4 gm = *reinterpret_cast<const float4*>(gamma + g * CPG + j * 4);
    const float4 bt = *reinterpret_cast<const float4*>(beta  + g * CPG + j * 4);

    const float* ibase = inp + (long long)n * HW * C + (long long)g * CPG;
    const float* rbase = res + (long long)n * HW * C + (long long)g * CPG;

    const int pstart = blk * chunk;
    int pend = pstart + chunk;
    if (pend > HW) pend = HW;

    for (int p0 = pstart; p0 < pend; p0 += PCHUNK) {
        const int p = p0 + pl;
        if (p < pend) {
            const long long off = (long long)p * C + j * 4;
            const float4 v = *reinterpret_cast<const float4*>(ibase + off);
            const float4 r = *reinterpret_cast<const float4*>(rbase + off);
            const int c0 = j * 4;
            sh[(c0 + 0) * (PCHUNK + 1) + pl] = silu_f((v.x - mean) * rstd * gm.x + bt.x) + r.x;
            sh[(c0 + 1) * (PCHUNK + 1) + pl] = silu_f((v.y - mean) * rstd * gm.y + bt.y) + r.y;
            sh[(c0 + 2) * (PCHUNK + 1) + pl] = silu_f((v.z - mean) * rstd * gm.z + bt.z) + r.z;
            sh[(c0 + 3) * (PCHUNK + 1) + pl] = silu_f((v.w - mean) * rstd * gm.w + bt.w) + r.w;
        }
        __syncthreads();

        const int cnt = (pend - p0) < PCHUNK ? (pend - p0) : PCHUNK;
#pragma unroll
        for (int it = 0; it < (CPG * PCHUNK) / NTHR; ++it) {
            const int idx = tid + it * NTHR;
            const int c   = idx / PCHUNK;
            const int lp  = idx - c * PCHUNK;
            if (lp < cnt) {
                const long long oidx =
                    ((long long)(n * C + g * CPG + c)) * HW + (long long)(p0 + lp);
                out[oidx] = sh[c * (PCHUNK + 1) + lp];
            }
        }
        __syncthreads();
    }
}

// ---------------------------------------------------------------------------
// Host helpers
// ---------------------------------------------------------------------------
static inline void pick_chunk(long long NG, int HW, int &chunk, int &K)
{
    const long long target_blocks = 2048;
    int k = (int)((target_blocks + NG - 1) / NG);
    if (k < 1) k = 1;
    int per = (HW + k - 1) / k;
    chunk = ((per + PCHUNK - 1) / PCHUNK) * PCHUNK;
    if (chunk < PCHUNK) chunk = PCHUNK;
    K = (HW + chunk - 1) / chunk;
}

static void run_stats(const torch::Tensor &inp, torch::Tensor &stats,
                      int N, int C, int G, int HW, int chunk, int K, double eps)
{
    auto stream = at::cuda::getCurrentCUDAStream();
    const long long NG = (long long)N * G;
    auto partial = torch::empty({NG * K * 2}, inp.options());

    dim3 grid(K, (unsigned)NG);
    gn_stats_kernel<<<grid, NTHR, 0, stream>>>(
        inp.data_ptr<float>(), partial.data_ptr<float>(), HW, C, G, chunk, K);
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    const float invcount = 1.0f / (float)((long long)CPG * HW);
    gn_finalize_kernel<<<(unsigned)NG, 32, 0, stream>>>(
        partial.data_ptr<float>(), stats.data_ptr<float>(), K, invcount, (float)eps);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

void nchw_to_nhwc_into(torch::Tensor src, torch::Tensor dst)
{
    TORCH_CHECK(src.is_cuda() && dst.is_cuda(), "inputs must be CUDA");
    TORCH_CHECK(src.scalar_type() == torch::kFloat32 &&
                dst.scalar_type() == torch::kFloat32, "fp32 only");
    TORCH_CHECK(src.dim() == 4 && dst.dim() == 4, "4D only");
    TORCH_CHECK(src.is_contiguous(), "src must be contiguous NCHW");
    TORCH_CHECK(dst.is_contiguous(at::MemoryFormat::ChannelsLast), "dst must be channels_last");
    TORCH_CHECK(src.sizes() == dst.sizes(), "size mismatch");

    const int N = (int)src.size(0), C = (int)src.size(1);
    const int H = (int)src.size(2), W = (int)src.size(3);
    const int HW = H * W;
    TORCH_CHECK((HW % 32) == 0 && (C % 32) == 0, "HW and C must be multiples of 32");

    auto stream = at::cuda::getCurrentCUDAStream();
    dim3 grid((unsigned)(HW / 32), (unsigned)(C / 32), (unsigned)N);
    dim3 block(32, 8, 1);
    nchw2nhwc_kernel<<<grid, block, 0, stream>>>(
        src.data_ptr<float>(), dst.data_ptr<float>(), HW, C);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

torch::Tensor gn_silu_nhwc(torch::Tensor inp, torch::Tensor gamma,
                           torch::Tensor beta, double eps)
{
    TORCH_CHECK(inp.is_cuda(), "input must be CUDA");
    TORCH_CHECK(inp.scalar_type() == torch::kFloat32, "fp32 only");
    TORCH_CHECK(inp.dim() == 4, "4D only");
    TORCH_CHECK(inp.is_contiguous(at::MemoryFormat::ChannelsLast), "need channels_last");

    const int N = (int)inp.size(0), C = (int)inp.size(1);
    const int H = (int)inp.size(2), W = (int)inp.size(3);
    const int G = 32, HW = H * W;
    TORCH_CHECK(C % G == 0 && (C / G) == CPG, "unsupported channel/group config");

    auto out = torch::empty_like(inp);           // preserves channels_last
    auto stats = torch::empty({(long long)N * G * 2}, inp.options());

    int chunk = 0, K = 0;
    pick_chunk((long long)N * G, HW, chunk, K);
    run_stats(inp, stats, N, C, G, HW, chunk, K, eps);

    auto stream = at::cuda::getCurrentCUDAStream();
    dim3 grid(K, (unsigned)((long long)N * G));
    gn_silu_apply_nhwc<<<grid, NTHR, 0, stream>>>(
        inp.data_ptr<float>(), out.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        stats.data_ptr<float>(), HW, C, G, chunk);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

torch::Tensor gn_silu_res_nchw(torch::Tensor inp, torch::Tensor gamma,
                               torch::Tensor beta, torch::Tensor res, double eps)
{
    TORCH_CHECK(inp.is_cuda() && res.is_cuda(), "inputs must be CUDA");
    TORCH_CHECK(inp.scalar_type() == torch::kFloat32 &&
                res.scalar_type() == torch::kFloat32, "fp32 only");
    TORCH_CHECK(inp.is_contiguous(at::MemoryFormat::ChannelsLast), "need channels_last");
    TORCH_CHECK(res.is_contiguous(at::MemoryFormat::ChannelsLast),
                "residual must be channels_last");

    const int N = (int)inp.size(0), C = (int)inp.size(1);
    const int H = (int)inp.size(2), W = (int)inp.size(3);
    const int G = 32, HW = H * W;
    TORCH_CHECK(C % G == 0 && (C / G) == CPG, "unsupported channel/group config");

    auto out = torch::empty({N, C, H, W}, inp.options());   // contiguous NCHW
    auto stats = torch::empty({(long long)N * G * 2}, inp.options());

    int chunk = 0, K = 0;
    pick_chunk((long long)N * G, HW, chunk, K);
    run_stats(inp, stats, N, C, G, HW, chunk, K, eps);

    auto stream = at::cuda::getCurrentCUDAStream();
    dim3 grid(K, (unsigned)((long long)N * G));
    gn_silu_res_apply_nchw<<<grid, NTHR, 0, stream>>>(
        inp.data_ptr<float>(), res.data_ptr<float>(), out.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        stats.data_ptr<float>(), HW, C, G, chunk);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
'''

_CPP_SRC = r'''
torch::Tensor gn_silu_nhwc(torch::Tensor inp, torch::Tensor gamma,
                           torch::Tensor beta, double eps);
torch::Tensor gn_silu_res_nchw(torch::Tensor inp, torch::Tensor gamma,
                               torch::Tensor beta, torch::Tensor res, double eps);
void nchw_to_nhwc_into(torch::Tensor src, torch::Tensor dst);
'''

_ext = load_inline(
    name="vae_resblock_gn_silu_fused_graph",
    cpp_sources=_CPP_SRC,
    cuda_sources=_CUDA_SRC,
    functions=["gn_silu_nhwc", "gn_silu_res_nchw", "nchw_to_nhwc_into"],
    verbose=False,
    extra_cflags=["-O3", "-std=c++20"],
    extra_cuda_cflags=[
        "-O3",
        "-std=c++20",
        "--expt-relaxed-constexpr",
        "-lineinfo",
        "-gencode=arch=compute_120,code=sm_120",
    ],
)


class ModelNew(nn.Module):
    """
    CUDA-graph capture/replay of the whole fused residual block on static
    channels_last buffers.  Per call: one custom tiled NCHW->NHWC transpose
    kernel + one graph replay.
    """

    def __init__(self):
        super().__init__()
        # graph state
        self._graph = None
        self._captured = False
        self._static_out = None
        # static buffers
        self._s_xc = None
        self._s_w1c = None
        self._s_w2c = None
        self._s_g1 = None
        self._s_b1 = None
        self._s_g2 = None
        self._s_b2 = None
        # bookkeeping
        self._sig = None
        self._param_refs = None      # keeps caller tensors alive => stable ptr identity
        self._param_ptrs = None
        self._recapture = 0
        self._graph_disabled = False
        self._tr_ok = True

    # ---- fused chain (captured) -------------------------------------------
    def _run_fused(self, xc, w1c, w2c, g1, b1, g2, b2, eps):
        y = F.conv2d(xc, w1c, None, 1, 1)
        y = _ext.gn_silu_nhwc(y, g1, b1, eps)
        y = F.conv2d(y, w2c, None, 1, 1)
        return _ext.gn_silu_res_nchw(y, g2, b2, xc, eps)

    # ---- fill the static NHWC input buffer --------------------------------
    def _fill_xc(self, x):
        src = x if x.is_contiguous() else x.contiguous()
        if self._tr_ok:
            try:
                _ext.nchw_to_nhwc_into(src, self._s_xc)
                return
            except Exception:
                self._tr_ok = False
        self._s_xc.copy_(src)

    # ---- refresh pinned parameter buffers if the caller changed tensors ----
    def _refresh_params(self, w1, w2, g1, b1, g2, b2):
        ptrs = (w1.data_ptr(), w2.data_ptr(), g1.data_ptr(),
                b1.data_ptr(), g2.data_ptr(), b2.data_ptr())
        if ptrs != self._param_ptrs:
            self._s_w1c.copy_(w1)
            self._s_w2c.copy_(w2)
            self._s_g1.copy_(g1)
            self._s_b1.copy_(b1)
            self._s_g2.copy_(g2)
            self._s_b2.copy_(b2)
            self._param_ptrs = ptrs
            self._param_refs = (w1, w2, g1, b1, g2, b2)

    # ---- one-time capture --------------------------------------------------
    def _capture(self, x, w1, w2, g1, b1, g2, b2, eps):
        cl = torch.channels_last

        self._s_xc = torch.empty_like(x, memory_format=cl)
        self._s_xc.copy_(x)
        self._s_w1c = torch.empty_like(w1, memory_format=cl)
        self._s_w2c = torch.empty_like(w2, memory_format=cl)
        self._s_g1 = torch.empty_like(g1, memory_format=torch.contiguous_format)
        self._s_b1 = torch.empty_like(b1, memory_format=torch.contiguous_format)
        self._s_g2 = torch.empty_like(g2, memory_format=torch.contiguous_format)
        self._s_b2 = torch.empty_like(b2, memory_format=torch.contiguous_format)

        self._param_ptrs = None
        self._refresh_params(w1, w2, g1, b1, g2, b2)

        s = torch.cuda.Stream()
        s.wait_stream(torch.cuda.current_stream())
        with torch.cuda.stream(s):
            tmp = None
            for _ in range(3):
                tmp = self._run_fused(self._s_xc, self._s_w1c, self._s_w2c,
                                      self._s_g1, self._s_b1,
                                      self._s_g2, self._s_b2, eps)
            del tmp
        torch.cuda.current_stream().wait_stream(s)
        torch.cuda.synchronize()

        g = torch.cuda.CUDAGraph()
        with torch.cuda.graph(g):
            self._static_out = self._run_fused(self._s_xc, self._s_w1c, self._s_w2c,
                                               self._s_g1, self._s_b1,
                                               self._s_g2, self._s_b2, eps)
        torch.cuda.synchronize()
        self._graph = g
        self._captured = True

    @torch.no_grad()
    def forward(self,
                x,
                conv1_weight,
                norm1_weight,
                norm1_bias,
                conv2_weight,
                norm2_weight,
                norm2_bias,
                eps):
        eps_f = eps if isinstance(eps, float) else float(eps)

        C = x.size(1)
        num_groups = 32
        cl = torch.channels_last

        supported = (x.is_cuda and x.dtype == torch.float32 and x.dim() == 4 and
                     C % num_groups == 0 and (C // num_groups) == 8 and
                     not self.training)

        if not supported:
            res = x if x.is_contiguous() else x.contiguous()
            out = F.conv2d(x, conv1_weight, None, 1, 1)
            out = F.silu(F.group_norm(out, num_groups, norm1_weight, norm1_bias, eps_f))
            out = F.conv2d(out, conv2_weight, None, 1, 1)
            out = F.silu(F.group_norm(out, num_groups, norm2_weight, norm2_bias, eps_f))
            return out + res

        w1 = conv1_weight if conv1_weight.is_contiguous(memory_format=cl) \
            else conv1_weight.contiguous(memory_format=cl)
        w2 = conv2_weight if conv2_weight.is_contiguous(memory_format=cl) \
            else conv2_weight.contiguous(memory_format=cl)
        g1 = norm1_weight if norm1_weight.is_contiguous() else norm1_weight.contiguous()
        b1 = norm1_bias if norm1_bias.is_contiguous() else norm1_bias.contiguous()
        g2 = norm2_weight if norm2_weight.is_contiguous() else norm2_weight.contiguous()
        b2 = norm2_bias if norm2_bias.is_contiguous() else norm2_bias.contiguous()

        # ---- graph path ----------------------------------------------------
        if not self._graph_disabled:
            sig = (tuple(x.shape), tuple(w1.shape), tuple(w2.shape), eps_f)
            if (not self._captured) or (sig != self._sig):
                if self._captured:
                    self._recapture += 1
                    if self._recapture > 2:
                        self._graph_disabled = True
                if not self._graph_disabled:
                    try:
                        self._graph = None
                        self._captured = False
                        self._capture(x, w1, w2, g1, b1, g2, b2, eps_f)
                        self._sig = sig
                    except Exception:
                        self._graph_disabled = True
                        self._captured = False

            if self._captured:
                self._refresh_params(w1, w2, g1, b1, g2, b2)
                self._fill_xc(x)
                self._graph.replay()
                return self._static_out

        # ---- non-graph fused fallback --------------------------------------
        xc = x if x.is_contiguous(memory_format=cl) else x.contiguous(memory_format=cl)
        return self._run_fused(xc, w1, w2, g1, b1, g2, b2, eps_f)
